package com.example

import com.example.ExamQuestionHelper.QSpec

internal object CivicsLiveExamLocalGovBank1 {
  private const val T = "විමධ්‍යගත පාලනය, පළාත් සභා හා පළාත් පාලන ආයතන"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("රාජ්‍ය පාලනයේදී තීරණ ගැනීමේ හා ක්‍රියාත්මක කිරීමේ සියලු බලතල මධ්‍යම ආණ්ඩුව සතුව තබාගැනීම හඳුන්වන්නේ කෙසේද?", "මධ්‍යගත පාලනය", "විමධ්‍යගත පාලනය", "බලය බෙදා හැරීම", "ස්වයංපාලනය", "සියලු පරිපාලන හා නීතිමය තීරණ අගනුවර කේන්ද්‍ර කරගත් තනි මධ්‍යස්ථානයකින් ගැනීම මධ්‍යගත පාලනයයි."),
    q("මධ්‍යම ආණ්ඩුව සතු ඇතැම් බලතල හා කාර්යයන් ප්‍රාදේශීය හෝ පළාත් ආයතන වෙත පැවරීමේ ක්‍රියාවලිය කුමක්ද?", "විමධ්‍යගතකරණය", "ඒකාධිපතිකරණය", "ජනසතුකරණය", "මධ්‍යගතකරණය", "පරිපාලන කාර්යක්ෂමතාව හා ජනතා සහභාගීත්වය වැඩි කිරීමට බලය ප්‍රාදේශීය මට්ටමට පැවරීම විමධ්‍යගතකරණයයි."),
    q("ව්‍යවස්ථාපිතව ප්‍රාදේශීය මට්ටමට නීති සෑදීමේ හා ප්‍රතිපත්ති තීරණ ගැනීමේ බලය පැවරීම හඳුන්වන විශේෂ පදය කුමක්ද?", "බලය බෙදා හැරීම (Devolution)", "පරිපාලන විතැන් කිරීම (Deconcentration)", "පෞද්ගලීකරණය", "ඒකපාක්ෂිකකරණය", "දිස්ත්‍රික් ලේකම්ට පරිපාලන බලය දීමට වඩා පළාත් සභා වැනි ඡන්දයෙන් පත්වන සභාවලට බලය දීම Devolution වේ."),
    q("මධ්‍යම රජයේ අමාත්‍යාංශයක කටයුතු ප්‍රාදේශීයව ක්‍රියාත්මක කිරීමට දිස්ත්‍රික් හෝ ප්‍රාදේශීය ලේකම්වරුන් පත් කිරීම කුමක්ද?", "පරිපාලන විමධ්‍යගතකරණය (Deconcentration)", "ව්‍යවස්ථාපිත බලය බෙදීම", "සන්ධීයකරණය", "පළාත් ස්වෛරීභාවය", "මධ්‍යම රජයේ වගකීම හා පාලනය යටතේම කාර්යාල ප්‍රාදේශීයව පිහිටුවීම පරිපාලන විමධ්‍යගතකරණයයි."),
    q("ශ්‍රී ලංකාවේ පළාත් සභා පද්ධතිය ස්ථාපිත කරන ලද්දේ කුමන ව්‍යවස්ථා සංශෝධනය මඟින්ද?", "1987 13 වන ආණ්ඩුක්‍රම ව්‍යවස්ථා සංශෝධනය", "1978 මුල් ව්‍යවස්ථාව", "2001 17 වන සංශෝධනය", "2015 19 වන සංශෝධනය", "1987 ජූලි ඉන්දු-ලංකා ගිවිසුමට අනුව 13 වන ව්‍යවස්ථා සංශෝධනයෙන් පළාත් සභා පිහිටුවන ලදී."),
    q("පළාත් සභා පිහිටුවීම හා එහි බලතල පිළිබඳ විස්තර 1978 ව්‍යවස්ථාවේ ඇතුළත් කර ඇත්තේ කුමන පරිච්ඡේදයේද?", "XVII අ (17A) පරිච්ඡේදය", "III පරිච්ඡේදය", "I පරිච්ඡේදය", "XX පරිච්ඡේදය", "13 වන සංශෝධනයෙන් ව්‍යවස්ථාවට එක් කළ 17අ පරිච්ඡේදය (154අ–154ත) පළාත් සභා පාලනය නියාමනය කරයි."),
    q("ශ්‍රී ලංකාව තුළ වර්තමානයේ පිහිටුවා ඇති මුළු පළාත් සභා සංඛ්‍යාව කීයද?", "පළාත් සභා 9", "පළාත් සභා 25", "පළාත් සභා 7", "පළාත් සභා 22", "රටේ පළාත් නවය සඳහා වෙන වෙනම පළාත් සභා 9ක් ස්ථාපිත කර ඇත."),
    q("1987 සිට 2006 දක්වා තාවකාලිකව ඒකාබද්ධ කර පවත්වාගෙන ගිය පළාත් සභා දෙක මොනවාද?", "උතුරු සහ නැගෙනහිර පළාත්", "බස්නාහිර සහ දකුණු පළාත්", "මධ්‍යම සහ සබරගමුව පළාත්", "වයඹ සහ උතුරු මැද පළාත්", "1987 දී උතුරු-නැගෙනහිර ඒකාබද්ධ කළද 2006 ශ්‍රේෂ්ඨාධිකරණ තීන්දුවෙන් ඒවා යළි වෙන් කෙරිණි."),
    q("පළාත් සභාවක නිල කාල සීමාව වසර කීයක්ද?", "අවුරුදු 5", "අවුරුදු 4", "අවුරුදු 6", "අවුරුදු 3", "154ඉ වගන්තිය අනුව පළාත් සභාවක සාමාන්‍ය නිල කාලය වසර 5කි."),
    q("පළාත් සභාවක විධායක බලතල ක්‍රියාත්මක කිරීමේ ප්‍රධානියා ලෙස ජනාධිපතිවරයා විසින් පත් කරන්නේ කවුද?", "පළාත් ආණ්ඩුකාරවරයා", "පළාත් ප්‍රධාන ලේකම්වරයා", "දිස්ත්‍රික් ලේකම්වරයා", "නගරාධිපතිවරයා", "154ආ වගන්තිය අනුව ජනාධිපතිවරයාගේ කැමැත්ත පරිදි වසර 5කට පළාත් ආණ්ඩුකාරවරයා පත් කෙරේ."),
    q("පළාත් සභාවක සභාපතිවරයා සහ උප සභාපතිවරයා පත් කර ගනු ලබන්නේ කෙසේද?", "පළාත් සභා මන්ත්‍රීවරුන්ගේ ඡන්දයෙන්", "ජනාධිපතිවරයාගේ නියෝගයෙන්", "මහේස්ත්‍රාත්වරයාගේ තීරණයෙන්", "ප්‍රාදේශීය ලේකම්වරුන්ගේ රැස්වීමෙන්", "පළාත් සභාව පාර්ලිමේන්තුවේ කථානායක මෙන් තම සභාව මෙහෙයවීමට සභාපතිවරයෙකු පත් කර ගනී."),
    q("පළාත් සභාවේ බහුතර පක්ෂයේ හෝ කණ්ඩායමේ නායකයා ලෙස ආණ්ඩුකාරවරයා විසින් පත් කරන තනතුර කුමක්ද?", "ප්‍රධාන අමාත්‍යවරයා", "පළාත් කොමසාරිස්වරයා", "දිසාපතිවරයා", "නගර ලේකම්වරයා", "පළාත් සභාවේ බහුතර විශ්වාසය දිනාගත් මන්ත්‍රීවරයා ප්‍රධාන අමාත්‍ය ධුරයට පත් කෙරේ."),
    q("ප්‍රධාන අමාත්‍යවරයාද ඇතුළුව එක් පළාත් සභාවක සිටිය හැකි උපරිම පළාත් අමාත්‍ය මණ්ඩල සංඛ්‍යාව කීයද?", "5", "10", "15", "3", "154ඊ වගන්තිය අනුව පළාත් සභාවේ ප්‍රධාන අමාත්‍යවරයාට අමතරව තවත් අමාත්‍යවරුන් 4කට වඩා නොසිටිය යුතුය."),
    q("පළාත් සභාවක් විසින් තමන්ට අයත් විෂයයන් සම්බන්ධයෙන් සම්මත කරන නීති හඳුන්වනු ලබන්නේ කුමන නමින්ද?", "පළාත් සභා ප්‍රඥප්ති (Statutes)", "පාර්ලිමේන්තු පනත්", "අතුරු ව්‍යවස්ථා", "කැබිනට් චක්‍රලේඛ", "පළාත් සභාවල ව්‍යවස්ථාදායක බලයෙන් සම්මත කරන නීති 'ප්‍රඥප්ති' ලෙස හැඳින්වේ."),
    q("පළාත් සභාවක් සම්මත කළ ප්‍රඥප්තියක් නීතියක් ලෙස බලාත්මක වීමට පෙර කාගේ අනුමැතිය හා අත්සන ලබාගත යුතුද?", "පළාත් ආණ්ඩුකාරවරයාගේ", "ශ්‍රේෂ්ඨාධිකරණ අගවිනිසුරුගේ", "විපක්ෂ නායකවරයාගේ", "මැතිවරණ කොමසාරිස්ගේ", "ප්‍රඥප්තියකට ආණ්ඩුකාරවරයාගේ අනුමැතිය ලැබීමෙන් පසු එය නීතිගත වේ."),
    q("1978 ව්‍යවස්ථාවේ නවවන උපලේඛනයේ (Ninth Schedule) ඇතුළත් ලැයිස්තු තුන කවරේද?", "පළාත් සභා ලැයිස්තුව, සංවෘත ලැයිස්තුව සහ සමගාමී ලැයිස්තුව", "ජාතික, පෞද්ගලික සහ වෙළඳ ලැයිස්තු", "ආදායම්, වියදම් සහ ණය ලැයිස්තු", "පාසල්, රෝහල් සහ පොලිස් ලැයිස්තු", "13 වන සංශෝධනයෙන් මධ්‍යම රජයේ හා පළාත් සභාවල බලතල බෙදීමට මෙම ලැයිස්තු තුන හඳුන්වා දුනි."),
    q("නවවන උපලේඛනයේ II වන ලැයිස්තුව වන 'සංවෘත ලැයිස්තුව' (Reserved List) යටතේ පවතින බලතල හිමිවන්නේ කාටද?", "මධ්‍යම රජයට", "පළාත් සභාවලට", "ප්‍රාදේශීය සභාවලට", "මහ නගර සභාවලට", "ජාතික ආරක්ෂාව, විදේශ කටයුතු හා මුදල් වැනි සංවෘත ලැයිස්තුවේ සියලු බලතල මධ්‍යම රජය සතුය."),
    q("පහත සඳහන් විෂයයන් අතරින් මධ්‍යම රජයේ සංවෘත ලැයිස්තුවට (Reserved List) අයත් වන්නේ කුමක්ද?", "ජාතික ආරක්ෂාව, විදේශ සබඳතා සහ මුදල්", "වරිපනම් බදු අය කිරීම", "පොදු වෙළඳපොළ නඩත්තුව", "ග්‍රාමීය පෙරපාසල් පාලනය", "ආරක්ෂාව, විදේශ ප්‍රතිපත්තිය, අධිකරණය, රේගුව හා තැපැල් සේවා සංවෘත ලැයිස්තුවේ ප්‍රධාන විෂයයන්ය."),
    q("සමගාමී ලැයිස්තුවේ (Concurrent List) විෂයයක් සම්බන්ධයෙන් පාර්ලිමේන්තු පනතක් හා පළාත් ප්‍රඥප්තියක් ගැටුණහොත් ප්‍රමුඛ වන්නේ කුමක්ද?", "පාර්ලිමේන්තු පනත", "පළාත් සභා ප්‍රඥප්තිය", "ප්‍රාදේශීය සභා අතුරු ව්‍යවස්ථාව", "දිස්ත්‍රික් ලේකම් නියෝගය", "ඒකීය රාජ්‍ය මූලධර්මය අනුව සමගාමී ලැයිස්තුවේදී මධ්‍යම පාර්ලිමේන්තු නීතිය ඉහළින් සැලකේ."),
    q("පළාත් සභා ලැයිස්තුවට (Provincial Council List) අයත් ප්‍රධාන විෂයයක් වන්නේ පහත සඳහන් කුමක්ද?", "පළාත් පාලන ආයතන අධීක්ෂණය හා පළාත් මාර්ග නඩත්තුව", "විදේශ තානාපති පත්වීම්", "ශ්‍රී ලංකා ගුවන් සේවය පාලනය", "මුදල් නෝට්ටු අච්චු ගැසීම", "පළාත් පාලනය, පළාත් අධ්‍යාපන පරිපාලනය, සෞඛ්‍ය හා කෘෂිකර්ම සේවා පළාත් ලැයිස්තුවට අයත්ය."),
    q("පළාත් නවය අතර රාජ්‍ය මූල්‍ය ප්‍රතිපාදන සාධාරණව බෙදා හැරීම සඳහා නිර්දේශ ඉදිරිපත් කරන ව්‍යවස්ථාපිත ආයතනය කුමක්ද?", "මුදල් කොමිෂන් සභාව (Finance Commission)", "මැතිවරණ කොමිෂන් සභාව", "රාජ්‍ය සේවා කොමිෂන් සභාව", "අධිකරණ සේවා කොමිෂන් සභාව", "154අආ වගන්තිය අනුව පළාත් සභාවල අවශ්‍යතා බලා මුදල් වෙන් කිරීම නිර්දේශ කරන්නේ මුදල් කොමිසමයි."),
    q("ශ්‍රී ලංකාවේ මුදල් කොමිෂන් සභාවේ නිල බලයෙන් සාමාජිකත්වය දරන නිලධාරීන් දෙදෙනා කවුද?", "ශ්‍රී ලංකා මහ බැංකු අධිපති හා මහා භාණ්ඩාගාර ලේකම්", "කථානායක හා අගවිනිසුරු", "පොලිස්පති හා නීතිපති", "විගණකාධිපති හා විදේශ ලේකම්", "154ආආ වගන්තිය අනුව ජනාධිපති පත් කරන තිදෙනෙකුට අමතරව මහ බැංකු අධිපති හා භාණ්ඩාගාර ලේකම් එහි සාමාජිකයෝ වෙති."),
    q("13 වන ව්‍යවස්ථා සංශෝධනයෙන් පළාත් මට්ටමින් අභියාචනා හා රීට් බලතල ක්‍රියාත්මක කිරීමට පිහිටුවූ අධිකරණය කුමක්ද?", "පළාත්බද මහාධිකරණය", "සමථ මණ්ඩලය", "ග්‍රාමීය උසාවිය", "පරිවාස අධිකරණය", "154ප වගන්තිය අනුව සෑම පළාතක් සඳහාම පළාත්බද මහාධිකරණයක් ස්ථාපිත කර ඇත."),
    q("පළාත් සභාවේ පරිපාලන සේවයේ ප්‍රධාන විධායක රාජ්‍ය නිලධාරියා ලෙස කටයුතු කරන්නේ කවුද?", "පළාත් ප්‍රධාන ලේකම් (Chief Secretary)", "මහා භාණ්ඩාගාර ලේකම්", "ග්‍රාම නිලධාරී", "පාර්ලිමේන්තු මහ ලේකම්", "ජනාධිපතිවරයා විසින් ප්‍රධාන අමාත්‍යවරයාගේ එකඟතාවයෙන් පත් කරන ප්‍රධාන ලේකම් පළාත් පරිපාලනය මෙහෙයවයි."),
    q("පළාත් රාජ්‍ය සේවයේ නිලධාරීන් පත් කිරීම, උසස් කිරීම හා විනය පාලනය සිදුකරන ආයතනය කුමක්ද?", "පළාත් රාජ්‍ය සේවා කොමිෂන් සභාව", "ජාතික මැතිවරණ කොමිසම", "අධිකරණ සේවා කොමිසම", "අල්ලස් කොමිසම", "පළාත් ගුරුවරුන් හා පළාත් නිලධාරීන් සම්බන්ධ කටයුතු පළාත් රාජ්‍ය සේවා කොමිසම මඟින් කෙරේ."),
    q("පළාත් සභාවක කිසියම් පළාත් සභා ලැයිස්තු පනත් කෙටුම්පතක් පාර්ලිමේන්තුව විසින් සම්මත කිරීමට අවශ්‍ය නම් කුමක් කළ යුතුද?", "පළාත් සභා සියල්ලෙන් අදහස් විමසීම හෝ පාර්ලිමේන්තු 2/3 බහුතරයකින් සම්මත කිරීම", "නගරාධිපතිවරුන්ගේ අත්සන් ගැනීම", "දිසා අධිකරණයේ නඩුවක් දැමීම", "සමථ මණ්ඩලයේ අනුමැතිය ගැනීම", "154උ(3) වගන්තිය අනුව පළාත් සභා එකඟ නොවේ නම් පාර්ලිමේන්තුවේ 2/3කින් සම්මත කළ යුතුය."),
    q("ශ්‍රී ලංකාව තුළ පවතින 'පළාත් සභා' පද්ධතිය මඟින් රටේ ඒකීය ස්වභාවය ආරක්ෂා වන්නේ කෙසේද?", "ව්‍යවස්ථාව සංශෝධනය කිරීමේ හා පරමාධිපත්‍යයේ අවසන් බලය මධ්‍යම පාර්ලිමේන්තුව සතුව පැවතීමෙන්", "පළාත්වලට වෙනම හමුදා පවත්වාගැනීමට ඉඩ දීමෙන්", "පළාත් සභාවලට වෙනම මුදල් ඒකකයක් දීමෙන්", "පළාත් සභාවලට වෙනම විදේශ තානාපති කාර්යාල දීමෙන්", "සන්ධීය රාජ්‍යයක මෙන් ප්‍රාන්තවලට වෙනම ව්‍යවස්ථා හෝ ස්වෛරීභාවයක් පළාත් සභාවලට නොමැත."),
    q("ප්‍රධාන අමාත්‍යවරයෙකු විසින් පළාත් සභාවේ විශ්වාසය අහිමි වූ විට කුමක් සිදුවේද?", "ප්‍රධාන අමාත්‍යවරයා හා පළාත් අමාත්‍ය මණ්ඩලය ඉල්ලා අස්විය යුතුය", "මධ්‍යම පාර්ලිමේන්තුව විසුරුවා හැරේ", "ශ්‍රේෂ්ඨාධිකරණය වසා දැමේ", "ආණ්ඩුකාරවරයා පාර්ලිමේන්තුවට පත්වේ", "පළාත් සභාවේ බහුතර විශ්වාසය නොමැති නම් විශ්වාසභංගයකින් ප්‍රධාන ඇමති ධුරය අහිමි වේ."),
    q("රටේ පරිපාලනය පහසු කිරීම සඳහා ශ්‍රී ලංකාව බෙදා ඇති පරිපාලන දිස්ත්‍රික්ක සංඛ්‍යාව කීයද?", "25", "22", "9", "18", "මැතිවරණ දිස්ත්‍රික්ක 22ක් වුවද පරිපාලන පහසුව සඳහා පරිපාලන දිස්ත්‍රික්ක 25ක් පවතී."),
    q("පරිපාලන දිස්ත්‍රික්කයක මධ්‍යම රජයේ නියෝජිතයා හා ප්‍රධාන පරිපාලන නිලධාරියා ලෙස ක්‍රියා කරන්නේ කවුද?", "දිස්ත්‍රික් ලේකම් (මහ දිසාපති)", "පළාත් ආණ්ඩුකාර", "නගරාධිපති", "ප්‍රාදේශීය සභා සභාපති", "දිස්ත්‍රික් ලේකම් කාර්යාලයේ (කච්චේරියේ) ප්‍රධානියා වන්නේ දිස්ත්‍රික් ලේකම්වරයාය."),
    q("පරිපාලන දිස්ත්‍රික්කයක් ඇතුළත බිම් මට්ටමින් මධ්‍යම රජයේ සේවාවන් (උප්පැන්න, හැඳුනුම්පත්, සුබසාධන) ජනතාවට සපයන ඒකකය කුමක්ද?", "ප්‍රාදේශීය ලේකම් කාර්යාලය", "ශ්‍රේෂ්ඨාධිකරණ රෙජිස්ට්‍රාර් කාර්යාලය", "විගණකාධිපති කාර්යාලය", "රේගු මූලස්ථානය", "1992 සිට ප්‍රාදේශීය ලේකම් කොට්ඨාස මඟින් පුරවැසියන්ට පරිපාලන සේවා කඩිනමින් සැපයේ."),
    q("ශ්‍රී ලංකාවේ ග්‍රාමීය මට්ටමින් පුරවැසියන් හා රජය අතර සෘජු සම්බන්ධතාව ගොඩනඟන කුඩාම පරිපාලන නිලධාරී වසම කුමක්ද?", "ග්‍රාම නිලධාරී වසම", "පළාත් සභා කලාපය", "මැතිවරණ දිස්ත්‍රික්කය", "මහ නගර කොට්ඨාසය", "ප්‍රාදේශීය ලේකම් කොට්ඨාසයක් ග්‍රාම නිලධාරී වසම් ගණනාවකට බෙදා ඇත."),
    q("දිස්ත්‍රික් ලේකම්වරයා හා ප්‍රාදේශීය ලේකම්වරුන් නියෝජනය කරන 'විමධ්‍යගත ආකෘතිය' පළාත් සභා ව්‍යුහයෙන් වෙනස් වන්නේ කෙසේද?", "මහජන ඡන්දයෙන් නොව රාජ්‍ය සේවා පත්වීමකින් මධ්‍යම රජයට වගකියන බැවිනි", "ඔවුන් විදේශ රටවලින් පත් කරන බැවිනි", "ඔවුන් නව පනත් සම්මත කරන බැවිනි", "ඔවුන්ට නඩු විභාග කිරීමේ බලය ඇති බැවිනි", "ලේකම් කාර්යාල පරිපාලන විමධ්‍යගතකරණය වන අතර පළාත් සභා දේශපාලන බලය බෙදාහැරීමකි."),
    q("පළාත් සභාවක සාමාන්‍ය අයවැය සකස් කර සභාවේ අනුමැතිය සඳහා ඉදිරිපත් කරන ප්‍රධාන වගකීම ඇත්තේ කාටද?", "ප්‍රධාන අමාත්‍යවරයා ප්‍රමුඛ පළාත් අමාත්‍ය මණ්ඩලයට", "ශ්‍රේෂ්ඨාධිකරණ විනිසුරුවරුන්ට", "පොලිස්පතිවරයාට", "තේරීම් භාර නිලධාරියාට", "ආණ්ඩුකාරවරයාගේ නිර්දේශය ඇතිව පළාත් අමාත්‍ය මණ්ඩලය පළාත් සභා අයවැය ඉදිරිපත් කරයි."),
    q("පළාත් සභාවක මූල්‍ය කටයුතු විගණනය කර වාර්තා නිකුත් කරන නිලධාරියා කවුද?", "ශ්‍රී ලංකාවේ විගණකාධිපතිවරයා", "මහ නගර කොමසාරිස්වරයා", "විපක්ෂ නායකවරයා", "පළාත් සභා සභාපතිවරයා", "ව්‍යවස්ථාවේ 154(1) වගන්තිය අනුව සියලු පළාත් සභා හා පළාත් පාලන ගිණුම් ජාතික විගණකාධිපති විගණනය කරයි."),
    q("ප්‍රාදේශීය හා පළාත් මට්ටමින් බලය බෙදාහැරීමෙන් සාමාන්‍ය පුරවැසියාට ලැබෙන ප්‍රධානතම ප්‍රතිලාභය කුමක්ද?", "ප්‍රදේශයේ අවශ්‍යතාවලට ගැළපෙන තීරණ කඩිනමින් හා අඩු වියදමින් ගැනීම", "කොළඹ නගරයට පමණක් සියලු සේවා සීමා වීම", "ඡන්ද බලය අහෝසි වීම", "පාසල් අධ්‍යාපනය නතර වීම", "කොළඹට නොගොස් ප්‍රාදේශීය ගැටලු ගැන ප්‍රාදේශීය නියෝජිතයන් මඟින් විසඳුම් ගත හැක."),
    q("හදිසි තත්ත්වයකදී හෝ පළාත් පරිපාලනය බිඳ වැටුණු අවස්ථාවක පළාත් සභාවේ විධායක බලය ජනාධිපතිවරයාට පවරාගත හැකි වගන්තිය කුමක්ද?", "154ඇ (154L / 154J) හදිසි බලතල වගන්ති", "10 වගන්තිය", "28 වගන්තිය", "126 වගන්තිය", "ආණ්ඩුක්‍රම ව්‍යවස්ථාව අනුව ක්‍රියා කළ නොහැකි විට ආණ්ඩුකාර වාර්තාව මත ජනාධිපතිට මැදිහත් විය හැක."),
    q("පළාත් සභාවක් තුළ පවතින 'ආණ්ඩුකාරවරයා සහ ප්‍රධාන අමාත්‍යවරයා අතර සබඳතාව' බොහෝ විට සමාන වන්නේ කුමන ආකෘතියටද?", "පාර්ලිමේන්තු ආකෘතියේ රාජ්‍ය නායකයා සහ අග්‍රාමාත්‍යවරයා අතර සබඳතාවට", "සෙනෙට් සභාව සහ දිසා අධිකරණය අතර සබඳතාවට", "ව්‍යාපාරික සමාගමක හා බැංකුවක සබඳතාවට", "තානාපති කාර්යාල දෙකක සබඳතාවට", "සාමාන්‍ය කටයුතුවලදී ආණ්ඩුකාරවරයා ප්‍රධාන අමාත්‍යවරයා ප්‍රමුඛ අමාත්‍ය මණ්ඩලයේ උපදෙස් මත ක්‍රියා කරයි."),
    q("1987 පළාත් සභා පනත හා 13 වන සංශෝධනය ගෙන ඒමට ආසන්නතම හේතුව වූ ජාතික ප්‍රශ්නය කුමක්ද?", "උතුරු-නැගෙනහිර ජනවාර්ගික අර්බුදයට දේශපාලන විසඳුමක් ලබාදීම", "ආර්ථික තේ වගාව පුළුල් කිරීම", "පෞද්ගලික විශ්වවිද්‍යාල ආරම්භ කිරීම", "වරාය නගරය ඉදිකිරීම", "බලය බෙදාහැරීම තුළින් ජාතික සංහිඳියාව හා සුළු ජාතීන්ගේ පාලන සහභාගීත්වය ඇති කිරීම අරමුණ විය."),
    q("පළාත් සභාවකට තම පළාත තුළ ආදායම් උපයා ගැනීමට නවවන උපලේඛනයෙන් පවරා ඇති මූලාශ්‍රයක් කුමක්ද?", "මෝටර් රථ බලපත්‍ර ගාස්තු, ව්‍යාපාර පිරිවැටුම් බදු හා මුද්දර ගාස්තු", "රේගු ආනයන බදු", "මුදල් නෝට්ටු නිකුත් කිරීම", "ගුවන්තොටුපළ බදු", "වාහන ආදායම් බලපත්‍ර ගාස්තු, සුරාබදු ඇතැම් කොටස් හා මුද්දර ගාස්තු පළාත් සභා ආදායම් මාර්ග වේ."),
    q("ශ්‍රී ලංකාවේ බස්නාහිර පළාතට අයත් වන පරිපාලන දිස්ත්‍රික්ක තුන කවරේද?", "කොළඹ, ගම්පහ සහ කළුතර", "කොළඹ, මහනුවර සහ ගාල්ල", "ගම්පහ, කුරුණෑගල සහ පුත්තලම", "කළුතර, රත්නපුර සහ මාතර", "ශ්‍රී ලංකාවේ වැඩිම ජන ඝනත්වය ඇති බස්නාහිර පළාත කොළඹ, ගම්පහ හා කළුතර දිස්ත්‍රික්කවලින් සමන්විතය."),
    q("පළාත් නවය අතරින් වැඩිම භූමි ප්‍රමාණයක් සහිත පළාත වන උතුරු මැද පළාතට අයත් දිස්ත්‍රික්ක දෙක මොනවාද?", "අනුරාධපුර සහ පොළොන්නරුව", "වවුනියාව සහ මන්නාරම", "මහනුවර සහ මාතලේ", "බදුල්ල සහ මොණරාගල", "අනුරාධපුරය සහ පොළොන්නරුව යන දිස්ත්‍රික්ක දෙක එක්ව උතුරු මැද පළාත සෑදේ."),
    q("පළාත් සභා පද්ධතිය යටතේ 'සබරගමුව පළාතට' අයත් දිස්ත්‍රික්ක දෙක කවරේද?", "රත්නපුර සහ කෑගල්ල", "බදුල්ල සහ නුවරඑළිය", "ගාල්ල සහ හම්බන්තොට", "කුරුණෑගල සහ පුත්තලම", "රත්නපුර සහ කෑගල්ල දිස්ත්‍රික්ක දෙක සබරගමුව පළාතට අයත් වේ."),
    q("ඌව පළාත සෑදෙන පරිපාලන දිස්ත්‍රික්ක දෙක කවරේද?", "බදුල්ල සහ මොණරාගල", "මාතලේ සහ නුවරඑළිය", "අම්පාර සහ මඩකලපුව", "රත්නපුර සහ හම්බන්තොට", "කඳුකර නැගෙනහිර හා ගිනිකොන පිහිටි බදුල්ල සහ මොණරාගල ඌව පළාතට අයත්ය."),
    q("මධ්‍යම රජයේ බලතල අමාත්‍යාංශ මට්ටමින් ග්‍රාමීය මට්ටම දක්වා බෙදා හැරීමේදී පවතින නිවැරදි පරිපාලන ධූරාවලිය කුමක්ද?", "මධ්‍යම රජය -> දිස්ත්‍රික් ලේකම් -> ප්‍රාදේශීය ලේකම් -> ග්‍රාම නිලධාරී", "ග්‍රාම නිලධාරී -> කැබිනට් මණ්ඩලය -> පළාත් සභාව -> ජනාධිපති", "ප්‍රාදේශීය සභාව -> අභියාචනාධිකරණය -> දිස්ත්‍රික් ලේකම්", "මහ බැංකුව -> පළාත් ආණ්ඩුකාර -> සමථ මණ්ඩලය", "මධ්‍යම රජයේ පරිපාලන සේවා කොළඹ සිට ග්‍රාම නිලධාරී වසම දක්වා මෙම අනුපිළිවෙළින් විමධ්‍යගත වේ."),
    q("පළාත් සභා විසුරුවා හැර පැවති කාලසීමාවකදී පළාත් පරිපාලනය බිඳ නොවැටී පවත්වාගෙන යාමේ වගකීම පැවරෙන්නේ කාටද?", "පළාත් ආණ්ඩුකාරවරයාට", "විපක්ෂ නායකවරයාට", "නගර සභා ලේකම්වරයාට", "මහාධිකරණ විනිසුරුට", "පළාත් සභාවේ නිල කාලය අවසන් වී මැතිවරණ පැවැත්වෙන තුරු පළාත් ප්‍රධාන ලේකම් හරහා ආණ්ඩුකාරවරයා පරිපාලනය කරයි."),
    q("රාජ්‍ය පාලනය විමධ්‍යගත කිරීම නිසා ප්‍රාදේශීය වශයෙන් නව නායකත්වයක් බිහිවීම ප්‍රජාතන්ත්‍රවාදයට වැදගත් වන්නේ ඇයි?", "ප්‍රාදේශීය ජන නායකයන්ට ජාතික නායකත්වය සඳහා පුහුණුව හා අත්දැකීම් ලැබෙන බැවිනි", "විදේශීය මැතිවරණ අවලංගු කළ හැකි බැවිනි", "කොළඹ ජනගහනය සම්පූර්ණයෙන් ඉවත් වන බැවිනි", "අධිකරණ පද්ධතිය අනවශ්‍ය වන බැවිනි", "බිම් මට්ටමේ ගැටලු විසඳමින් මතු වන දේශපාලනඥයන් අනාගත ජාතික පාලනයට සූදානම් වේ."),
    q("සන්ධීය (Federal) ක්‍රමයක ප්‍රාන්ත රාජ්‍ය සහ ශ්‍රී ලංකාවේ පළාත් සභා අතර ප්‍රධාන වෙනස කුමක්ද?", "සන්ධීය ප්‍රාන්තවලට ස්වෛරී ව්‍යවස්ථා බලය ඇති නමුත් පළාත් සභා ඒකීය ව්‍යවස්ථාවට යටත්ය", "සන්ධීය ප්‍රාන්තවලට පාසල් හෝ මාර්ග නැත", "ශ්‍රී ලංකාවේ පළාත් සභාවලට වෙනම යුද හමුදා ඇත", "සන්ධීය ක්‍රමයේ මැතිවරණ නොපැවැත්වේ", "ඇමරිකාව හෝ ඉන්දියාව මෙන් සන්ධීය ප්‍රාන්ත නොව ශ්‍රී ලංකාවේ පළාත් සභා මධ්‍යම ව්‍යවස්ථාව යටතේ ක්‍රියා කරයි."),
    q("පළාත් සභාවක සභිකයෙකු වීම සඳහා නියෝජනය කළ හැකි අවම වයස් සීමාව කුමක්ද?", "අවුරුදු 18", "අවුරුදු 35", "අවුරුදු 30", "අවුරුදු 25", "පාර්ලිමේන්තු මැතිවරණයට මෙන් ඡන්ද හිමි නාමලේඛනයේ ලියාපදිංචි අවුරුදු 18ට වැඩි පුරවැසියන්ට තරග කළ හැක."),
    q("පළාත් සභා ලැයිස්තුවේ පොලිස් හා ඉඩම් බලතල සම්බන්ධ විශේෂ විධිවිධාන ඇතුළත් වන්නේ නවවන උපලේඛනයේ කුමන කොටසේද?", "I වන හා II වන පරිශිෂ්ටවල (Appendix I & II)", "IV වන පරිච්ඡේදයේ", "XII වන උපලේඛනයේ", "38 වන වගන්තියේ", "13 වන සංශෝධනයේ පොලිස් බලතල I වන පරිශිෂ්ටයේද, ඉඩම් බලතල II වන පරිශිෂ්ටයේද සවිස්තර කර ඇත."),
    q("ශ්‍රී ලංකාවේ ප්‍රථම පළාත් සභා මැතිවරණ පැවැත්වුණේ කුමන වර්ෂයේදීද?", "1988", "1978", "1983", "1994", "13 වන සංශෝධනයෙන් පසු 1988 අප්‍රේල්-ජූනි සහ නොවැම්බර් මාසවල පළමු පළාත් සභා මැතිවරණ පැවැත්වුණි."),
    q("විමධ්‍යගත පාලනය යටතේ 'සංවර්ධන සැලසුම් සකස් කිරීමේදී' ප්‍රාදේශීය ප්‍රජාවගේ අදහස් ලබාගැනීමෙන් සිදුවන ප්‍රධාන වාසිය කුමක්ද?", "සැබෑ ප්‍රාදේශීය අවශ්‍යතා හඳුනාගෙන සම්පත් නාස්තිය වැළැක්වීම", "ව්‍යාපෘති කාලය වසර දහයකින් ප්‍රමාද කිරීම", "විදේශීය සමාගම්වලට පමණක් ලාභ දීම", "ග්‍රාමීය පාසල් වසා දැමීම", "බිම් මට්ටමේ ජනතාවගේ ප්‍රමුඛතා අනුව මාර්ග, ජල හා පාසල් ව්‍යාපෘති සැලසුම් කිරීමෙන් ඵලදායීතාව වැඩිවේ."),
    q("පළාත් මට්ටමින් ඉහළ ජාතික ප්‍රමිතීන් හා විෂය මාලා ආරක්ෂා කිරීම සඳහා පාසල් අධ්‍යාපනයේ විෂය නිර්දේශ හා ජාතික විභාග සැකසීම අයත් වන්නේ කාටද?", "මධ්‍යම රජයේ අධ්‍යාපන අමාත්‍යාංශයට හා විභාග දෙපාර්තමේන්තුවට", "ප්‍රාදේශීය සභාවට", "මහ නගර සභාවට", "පළාත් ක්‍රීඩා සංගමයට", "පළාත් පාසල් පරිපාලනය පළාත් සභාවට හිමි වුවද ජාතික පාසල්, විෂය මාලා හා ජාතික විභාග මධ්‍යම රජය සතුය."),
    q("රටේ පරිපාලනය අධික ලෙස මධ්‍යගත වීම නිසා ඇතිවිය හැකි ප්‍රධාන අවාසියක් කුමක්ද?", "ප්‍රාදේශීය ගැටලු විසඳීමේදී ප්‍රමාදය හා ප්‍රදේශ අතර සංවර්ධන විෂමතා ඇතිවීම", "පළාත් සභා ආදායම් දෙගුණ වීම", "ග්‍රාම නිලධාරීන් සංඛ්‍යාව වැඩි වීම", "ජනතා සහභාගීත්වය ඉහළ යාම", "සෑම කුඩා තීරණයක්ම අගනුවර අනුමැතියට රැඳී සිටීමෙන් පරිපාලන ප්‍රමාද හා අසමතුලිතතා ඇතිවේ."),
    q("බලය බෙදා හැරීම තුළ 'සමානුපාතික සංවර්ධනයක්' ඇති කිරීම සඳහා මුදල් කොමිෂන් සභාව අනුගමනය කරන මූලධර්මය කුමක්ද?", "පළාත් අතර ආර්ථික හා යටිතල පහසුකම් විෂමතාව ක්‍රමයෙන් අඩු කිරීම", "කොළඹ දිස්ත්‍රික්කයට පමණක් මුළු මුදල දීම", "දියුණු පළාත්වලට පමණක් ප්‍රතිපාදන වැඩි කිරීම", "මධ්‍යම රජයේ සියලු ආදායම් බෙදාගැනීම නතර කිරීම", "පසුගාමී පළාත්වල සෞඛ්‍ය, අධ්‍යාපන හා මාර්ග දියුණු කිරීමට ප්‍රමුඛතාව දී මුදල් වෙන් කෙරේ."),
    q("පළාත් සභාවක වාර්ෂික ගිණුම් හා වියදම් විමර්ශනය කිරීම සඳහා පළාත් සභාව තුළ පිහිටුවා ඇති කාරක සභාව කුමක්ද?", "පළාත් සභා ගිණුම් කාරක සභාව", "ශ්‍රේෂ්ඨාධිකරණ කාරක සභාව", "විදේශ සබඳතා කමිටුව", "ආරක්ෂක කවුන්සිලය", "ජාතික පාර්ලිමේන්තුවේ COPA කමිටුව මෙන් පළාත් සභාවලද මූල්‍ය විනය පරීක්ෂාවට ගිණුම් කාරක සභා ඇත."),
    q("වයඹ පළාතට අයත් වන පරිපාලන දිස්ත්‍රික්ක දෙක මොනවාද?", "කුරුණෑගල සහ පුත්තලම", "මාතලේ සහ මහනුවර", "අනුරාධපුර සහ පොළොන්නරුව", "ගාල්ල සහ මාතර", "කුරුණෑගල සහ පුත්තලම දිස්ත්‍රික්ක දෙක එක්ව වයඹ පළාත සමන්විත වේ."),
    q("දකුණු පළාතට අයත් වන පරිපාලන දිස්ත්‍රික්ක තුන කවරේද?", "ගාල්ල, මාතර සහ හම්බන්තොට", "කළුතර, ගාල්ල සහ රත්නපුර", "මාතර, මොණරාගල සහ බදුල්ල", "හම්බන්තොට, අම්පාර සහ මඩකලපුව", "ගාල්ල, මාතර හා හම්බන්තොට යන දිස්ත්‍රික්ක තුන දකුණු පළාතට අයත් වේ."),
    q("නැගෙනහිර පළාතට අයත් වන පරිපාලන දිස්ත්‍රික්ක තුන මොනවාද?", "ත්‍රිකුණාමලය, මඩකලපුව සහ අම්පාර", "යාපනය, වවුනියාව සහ මුලතිව්", "පොළොන්නරුව, මාතලේ සහ බදුල්ල", "අම්පාර, මොණරාගල සහ හම්බන්තොට", "බහුවාර්ගික ජන සංයුතියකින් යුත් ත්‍රිකුණාමලය, මඩකලපුව හා අම්පාර නැගෙනහිර පළාත සාදයි."),
    q("උතුරු පළාතට අයත් වන පරිපාලන දිස්ත්‍රික්ක පහ කවරේද?", "යාපනය, කිලිනොච්චිය, මන්නාරම, වවුනියාව සහ මුලතිව්", "යාපනය, අනුරාධපුර, ත්‍රිකුණාමලය, මන්නාරම සහ මුලතිව්", "කිලිනොච්චිය, පුත්තලම, වවුනියාව, මන්නාරම සහ කුරුණෑගල", "යාපනය, මඩකලපුව, අම්පාර, වවුනියාව සහ මුලතිව්", "උතුරු පළාත යාපනය, කිලිනොච්චිය, මන්නාරම, මුලතිව් සහ වවුනියාව යන දිස්ත්‍රික්ක පහෙන් සමන්විතය."),
    q("මධ්‍යම පළාතට අයත් වන පරිපාලන දිස්ත්‍රික්ක තුන මොනවාද?", "මහනුවර, මාතලේ සහ නුවරඑළිය", "මහනුවර, කෑගල්ල සහ රත්නපුර", "නුවරඑළිය, බදුල්ල සහ කුරුණෑගල", "මාතලේ, පොළොන්නරුව සහ අනුරාධපුර", "මධ්‍යම කඳුකරයේ පිහිටි මහනුවර, මාතලේ හා නුවරඑළිය මධ්‍යම පළාතට අයත්ය."),
    q("දේශීය හා ප්‍රාදේශීය වශයෙන් 'ද්විත්ව පාලනයක් හෝ අධික පරිපාලන වියදම් ඇතිවීම' කුමන ක්‍රමයක අවාසියක් ලෙස ඇතැම් විචාරකයන් දක්වයිද?", "අකාර්යක්ෂම ලෙස ක්‍රියාත්මක වන විමධ්‍යගත පාලන ක්‍රමයේ", "සරල බහුතර ඡන්ද ක්‍රමයේ", "ඒකපාක්ෂික ආණ්ඩු ක්‍රමයේ", "සමථ මණ්ඩල ක්‍රමයේ", "මධ්‍යම අමාත්‍යාංශ හා පළාත් අමාත්‍යාංශ අතර නිසි සම්බන්ධීකරණයක් නොමැති විට නාස්තිය හා ගැටුම් ඇතිවිය හැක."),
    q("පළාත් සභාවක සම්මත කරන ප්‍රඥප්තියක් ආණ්ඩුක්‍රම ව්‍යවස්ථාවට පටහැනි බවට සැකයක් ඇති වුවහොත් ආණ්ඩුකාරවරයාට කුමක් කළ හැකිද?", "අනුමත නොකර පළාත් සභාවට හෝ ජනාධිපති මඟින් ශ්‍රේෂ්ඨාධිකරණයට යොමු කිරීම", "වහාම පළාත් සභා මන්ත්‍රීන් අත්අඩංගුවට ගැනීම", "පාර්ලිමේන්තුව විසුරුවා හැරීම", "දිස්ත්‍රික් ලේකම් කාර්යාලය වසා දැමීම", "ආණ්ඩුකාරවරයාට ප්‍රඥප්තිය නැවත සලකා බැලීමට යැවීමට හෝ ජනාධිපති මඟින් ශ්‍රේෂ්ඨාධිකරණ මතය විමසීමට හැක."),
    q("පළාත් සභාවට අයත් පොදු සේවාවක් වන 'ප්‍රාථමික හා ද්විතීයික රෝහල් පරිපාලනය' හා 'ග්‍රාමීය සෞඛ්‍ය මධ්‍යස්ථාන' තුළින් ජනතාවට ලැබෙන පහසුව කුමක්ද?", "තම පළාත තුළම කඩිනමින් වෛද්‍ය ප්‍රතිකාර හා මාතෘ සායන පහසුකම් ලැබීම", "පෞද්ගලික රෝහල් සියල්ල වැසී යාම", "ඖෂධ ආනයනය පළාත් සභාව තනිව කිරීම", "ජාතික රෝහල අහෝසි වීම", "ප්‍රාදේශීය හා දිස්ත්‍රික් රෝහල් පළාත් සභා මඟින් පාලනය වීමෙන් ප්‍රජා සෞඛ්‍ය සේවා ප්‍රවේශය පුළුල් වේ."),
    q("ප්‍රාදේශීය ලේකම් කොට්ඨාසයක සිදුකරන සංවර්ධන හා සුබසාධන කටයුතු (උදාහරණයක් ලෙස අස්වැසුම හෝ ගොවි සහනාධාර) නිසි ප්‍රතිලාභීන්ට ලැබෙන්නේ කෙසේද?", "ග්‍රාම නිලධාරී හා සංවර්ධන නිලධාරීන්ගේ ක්ෂේත්‍ර පරීක්ෂාව හා ප්‍රාදේශීය කමිටු මඟින්", "පාර්ලිමේන්තු විවාද මඟින් පමණක්", "ශ්‍රේෂ්ඨාධිකරණ නඩු තීන්දු මඟින්", "විදේශ තානාපති කාර්යාල මඟින්", "ප්‍රාදේශීය ලේකම් කාර්යාලය හා ග්‍රාම නිලධාරීන් බිම් මට්ටමින් සුදුසුකම් තහවුරු කර සහන සපයයි."),
    q("පළාත් සභාවක් සඳහා වෙන් කර ඇති මුළු මන්ත්‍රී ආසන සංඛ්‍යාව තීරණය වන්නේ කුමන සාධක මතද?", "අදාළ පළාතේ ජනගහනය සහ භූමි ප්‍රමාණය මත", "පළාතේ පාසල් සංඛ්‍යාව මත", "විදේශ සංචාරකයන් සංඛ්‍යාව මත", "රාජ්‍ය සේවකයන් ගණන මත", "පළාතේ ජනගහනය (40,000කට 1ක්) හා භූමි ප්‍රමාණය (වර්ග කි.මී. 1,000කට 1ක්) අනුව සභික ගණන තීරණය වේ."),
    q("පළාත් සභා ක්‍රමයේදී ආණ්ඩුකාරවරයාගේ භූමිකාව විවාදයට ලක්වීමට ප්‍රධාන හේතුවක් වන්නේ කුමක්ද?", "මහජන ඡන්දයෙන් තේරී පත් වූ ප්‍රධාන ඇමතිට වඩා ඇතැම් විධායක බලතල පත් කළ ආණ්ඩුකාරවරයා සතු වීම", "ආණ්ඩුකාරවරයාට කිසිදු රාජකාරියක් නොතිබීම", "ආණ්ඩුකාරවරයා විදේශ පුරවැසියෙකු වීම", "ආණ්ඩුකාරවරයා පාර්ලිමේන්තු මන්ත්‍රීවරයෙකු වීම", "13 වන සංශෝධනයේ බලය බෙදීම තුළ ආණ්ඩුකාර බලතල සීමා කිරීම පිළිබඳ විවිධ ව්‍යවස්ථා සංවාද පවතී."),
    q("පළාත් පාලන ආයතන (මහ නගර සභා, නගර සභා, ප්‍රාදේශීය සභා) අධීක්ෂණය කිරීමේ බලය පළාත් සභා ලැයිස්තුවට අයත් වුවද පළාත් පාලන මැතිවරණ පවත්වන්නේ කවුද?", "ජාතික මැතිවරණ කොමිෂන් සභාව", "පළාත් ආණ්ඩුකාරවරයා", "පළාත් ප්‍රධාන ලේකම්වරයා", "නගරාධිපතිවරයා", "සෑම මට්ටමකම මැතිවරණ පැවැත්වීමේ ස්වාධීන බලය ජාතික මැතිවරණ කොමිෂන් සභාව සතුය."),
    q("මධ්‍යම රජය හා පළාත් සභා අතර සම්බන්ධීකරණය ශක්තිමත් කිරීමට පිහිටුවා ඇති අමාත්‍යාංශය කුමක්ද?", "රාජ්‍ය පරිපාලන, ස්වදේශ කටයුතු හා පළාත් සභා අමාත්‍යාංශය", "විදේශ කටයුතු අමාත්‍යාංශය", "විදේශ රැකියා අමාත්‍යාංශය", "වරාය හා නාවික අමාත්‍යාංශය", "පළාත් සභා හා පළාත් පාලන කටයුතු සම්බන්ධ ජාතික ප්‍රතිපත්ති සම්බන්ධීකරණය මේ අමාත්‍යාංශයෙන් සිදු කෙරේ."),
    q("දිස්ත්‍රික් සංවර්ධන සැලසුම් සම්පාදනයේදී මධ්‍යම රජයේ මන්ත්‍රීවරුන්, පළාත් සභා හා පළාත් පාලන නියෝජිතයන් එක්වන සභාව කුමක්ද?", "දිස්ත්‍රික් සම්බන්ධීකරණ කමිටුව (DCC)", "ශ්‍රේෂ්ඨාධිකරණ සභාව", "මුදල් මණ්ඩලය", "සමථ කොමිසම", "දිස්ත්‍රික්කයේ සංවර්ධන ව්‍යාපෘති සමපාත නොවී ක්‍රියාත්මක කිරීමට මෙම කමිටුව ක්‍රියා කරයි."),
    q("ශ්‍රී ලංකාවේ බලය විමධ්‍යගත කිරීමේ ඉතිහාසයේ 1980 දී පිහිටුවන ලද දිස්ත්‍රික් මට්ටමේ නියෝජිත ආයතනය කුමක් වීද?", "දිස්ත්‍රික් සංවර්ධන සභා (DDC)", "ගම්සභා ක්‍රමය", "සෙනෙට් සභාව", "රාජ්‍ය මන්ත්‍රණ සභාව", "පළාත් සභාවලට පෙර 1980 දී බලය විමධ්‍යගත කිරීමේ පියවරක් ලෙස දිස්ත්‍රික් සංවර්ධන සභා පිහිටුවනු ලැබීය."),
    q("පළාත් සභාවක සභා රැස්වීම්වලදී තීරණ ගනු ලබන්නේ කුමන ප්‍රජාතන්ත්‍රවාදී මූලධර්මය අනුවද?", "බහුතර සභික ඡන්දයෙන්", "ආණ්ඩුකාරවරයාගේ තනි ඡන්දයෙන්", "ලේකම්වරයාගේ තීරණයෙන්", "පොලිස් නිර්දේශයෙන්", "නියෝජිත සභාවක් ලෙස සාකච්ඡා හා විවාදවලින් පසු බහුතර කැමැත්තෙන් තීරණ අනුමත කෙරේ."),
    q("විමධ්‍යගත පාලනය තුළ 'සහායකත්ව මූලධර්මය' (Principle of Subsidiarity) යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "පහළ මට්ටමින් කාර්යක්ෂමව කළ හැකි කාර්යයන් ඉහළ මට්ටමට නොගෙන ප්‍රාදේශීයව ඉටු කිරීම", "සියලුම වැඩ ජනාධිපති කාර්යාලයට පැවරීම", "පළාත් පාලන ආයතන සම්පූර්ණයෙන් ඉවත් කිරීම", "බදු අය කිරීම අත්හිටුවීම", "පුරවැසියාට සමීපතම ආයතනයට හැකිතාක් වගකීම් පැවරීම යහපාලන මූලධර්මයකි."),
    q("පළාත් සභා ලැයිස්තුව යටතේ ග්‍රාමීය ආර්ථිකය නගා සිටුවීමට පළාත් සභා විසින් මෙහෙයවන ප්‍රධාන සේවාවක් කුමක්ද?", "සමුපකාර සංවර්ධනය හා කුඩා කර්මාන්ත ප්‍රවර්ධනය", "ගුවන් තොටුපළ පාලනය", "නාවික හමුදා පුහුණුව", "විදේශ ණය ගිවිසුම් අත්සන් කිරීම", "පළාත් සමුපකාර, පශු සම්පත් හා කෘෂි ව්‍යාප්ති සේවා ප්‍රාදේශීය ආර්ථිකය ශක්තිමත් කරයි."),
    q("සෑම පළාත් සභාවකම සංයුතිය තුළ ජනගහනයෙන් අඩු කොටස් නියෝජනය වන බවට සහතික කිරීමට භාවිත කළ මැතිවරණ ක්‍රමය කුමක්ද?", "දිස්ත්‍රික් සමානුපාතික නියෝජන ක්‍රමය", "රාජකීය නාමකරණය", "සීමිත ඡන්ද බලය", "බහුවිධ ඡන්ද ක්‍රමය", "පළාත් සභා මැතිවරණවලදී දිස්ත්‍රික් සමානුපාතික ක්‍රමය හා ප්‍රසාද ආසන 2ක් ජයග්‍රාහී පක්ෂයට හිමිවිය."),
    q("පළාත් සභාවල බලතල ක්‍රියාත්මක වන විට පාර්ලිමේන්තුව හා පළාත් සභා අතර ව්‍යවස්ථා ගැටුමක් විසඳීමේ අවසන් අධිකරණ බලය ඇත්තේ කාටද?", "ශ්‍රේෂ්ඨාධිකරණයට", "මහේස්ත්‍රාත් අධිකරණයට", "පළාත් සභා සභාපතිට", "දිස්ත්‍රික් ලේකම්ට", "ව්‍යවස්ථාව අර්ථනිරූපණය කිරීමේ හා ප්‍රඥප්ති ව්‍යවස්ථානුකූල බව තීරණය කිරීමේ අවසන් බලය ශ්‍රේෂ්ඨාධිකරණය සතුය."),
    q("ශ්‍රී ලංකාවේ පළාත් නවයෙන් වැඩිම ජනගහනයක් ජීවත් වන සහ වැඩිම ආර්ථික දායකත්වයක් සපයන පළාත කුමක්ද?", "බස්නාහිර පළාත", "ඌව පළාත", "උතුරු මැද පළාත", "උතුරු පළාත", "කොළඹ, ගම්පහ හා කළුතර දිස්ත්‍රික්ක අයත් බස්නාහිර පළාත රටේ ප්‍රධාන වාණිජ හා ජනාකීර්ණ කලාපයයි."),
    q("පළාත් සභාවල 'අන්තර් පළාත් සහයෝගීතාව' (Inter-Provincial Cooperation) වැදගත් වන්නේ කුමන ව්‍යාපෘති සඳහාද?", "පළාත් දෙකක් හරහා යන ගංගා, මාර්ග හා වාරිමාර්ග සංවර්ධනයට", "විදේශ යුද්ධ මෙහෙයවීමට", "අලුත් මුදල් ඒකක නිපදවීමට", "තානාපති කාර්යාල පවත්වාගෙන යාමට", "පළාත් මායිම් ඉක්මවන පාරිසරික හා යටිතල පහසුකම් ගැටලු පළාත් සභා සහයෝගීතාවෙන් විසඳිය හැක."),
    q("දේශීය හා ප්‍රාදේශීය මට්ටමින් රාජ්‍ය පරිපාලනය සිදු කිරීමේදී 'ග්‍රාමීය සංවර්ධනය සඳහා ප්‍රාදේශීය මට්ටමින් පුරවැසි කමිටු' සම්බන්ධ කර ගැනීමෙන් සිදුවන්නේ කුමක්ද?", "ව්‍යාපෘති කෙරෙහි ප්‍රජා අයිතිය, විනිවිදභාවය හා නඩත්තුව තහවුරු වීම", "රාජ්‍ය සේවකයන් සම්පූර්ණයෙන් ඉවත් කිරීම", "බදු අය කිරීම නතර කිරීම", "මැතිවරණ කල් දැමීම", "ජනතා සහභාගීත්ව සංවර්ධනය තුළින් ප්‍රාදේශීය ව්‍යාපෘති දීර්ඝකාලීනව සාර්ථක වේ.")
  )
}
